from collections import defaultdict, deque

def read_ints():
    return list(map(int, input().split()))

def bfs(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    path = []
    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                path.append((node, neighbor, neighbor))
                queue.append(neighbor)
                break

    return path

